use madh;


drop table if exists company_employee_salary;

CREATE TABLE `company_employee_salary` (
  `employee_id` INT,
  `employee_name` VARCHAR(20),
  `department` VARCHAR(20),
  `job_role` VARCHAR(30),
  `experience_years` INT,
  `salary` INT,
  `performance_score` DECIMAL(10,2),
  `location` VARCHAR(20)
);

