select * from  company_employee_salary;



-- 1. Total number of employees
SELECT COUNT(*) AS total_employees
FROM company_employee_salary;

-- 2. Highest salary
SELECT MAX(salary) AS highest_salary
FROM company_employee_salary;

-- 3. Lowest salary
SELECT MIN(salary) AS lowest_salary
FROM company_employee_salary;

-- 4. Average salary
SELECT AVG(salary) AS average_salary
FROM company_employee_salary;

-- 5. Total salary paid
SELECT SUM(salary) AS total_salary
FROM company_employee_salary;



-- 6. Number of employees in each department

SELECT department, COUNT(*) AS employee_count
FROM company_employee_salary
GROUP BY department;

-- 7. Average salary by department

SELECT department, AVG(salary) AS average_salary
FROM company_employee_salary
GROUP BY department;

-- 8. Highest salary in each department
SELECT department, MAX(salary) AS highest_salary
FROM company_employee_salary
GROUP BY department;

-- 9. Department-wise total salary

SELECT department, SUM(salary) AS total_salary
FROM company_employee_salary
GROUP BY department
ORDER BY total_salary DESC;


-- 10. Top 10 highest-paid employees


SELECT employee_name, department, job_role, salary
FROM company_employee_salary
ORDER BY salary DESC
LIMIT 10;

-- 11. Employees earning more than 70000

SELECT *
FROM company_employee_salary
WHERE salary > 70000;

-- 12. Employees with more than 5 years experience
SELECT employee_name, experience_years, salary
FROM company_employee_salary
WHERE experience_years > 5
ORDER BY experience_years DESC;

-- 13. Employees with salary between 50000 and 80000
SELECT employee_name, salary
FROM company_employee_salary
WHERE salary BETWEEN 50000 AND 80000;



-- 14. Average performance score by department


SELECT department, AVG(performance_score) AS avg_performance
FROM company_employee_salary
GROUP BY department;

-- 15. Employees with performance score 4 or above


SELECT employee_name, department, performance_score, salary
FROM company_employee_salary
WHERE performance_score >= 4
ORDER BY performance_score DESC;




-- 16. Number of employees in each location


SELECT location, COUNT(*) AS employee_count
FROM company_employee_salary
GROUP BY location
ORDER BY employee_count DESC;

-- 17. Average salary by location
SELECT location, AVG(salary) AS average_salary
FROM company_employee_salary
GROUP BY location
ORDER BY average_salary DESC;




SELECT employee_name, department, job_role, salary
FROM company_employee_salary
WHERE salary > (
    SELECT AVG(salary)
    FROM company_employee_salary
)
ORDER BY salary DESC;



SELECT 
    employee_name,
    salary,
    CASE
        WHEN salary < 40000 THEN 'Low Salary'
        WHEN salary BETWEEN 40000 AND 70000 THEN 'Medium Salary'
        ELSE 'High Salary'
    END AS salary_category
FROM company_employee_salary;



SELECT *
FROM company_employee_salary
ORDER BY salary DESC
LIMIT 10 OFFSET 10;

CREATE TABLE company_employee_salary_2 (
    employee_id INT,
    employee_name VARCHAR(20),
    department VARCHAR(20),
    job_role VARCHAR(30),
    experience_years INT,
    salary INT,
    performance_score DECIMAL(10,2),
    location VARCHAR(20)
);



