       job_role, experience_years, salary,
       performance_score, location
FROM company_employee_salary_2;


SELECT
    e.employee_id,
    e.employee_name,
    e.department,
    e.salary,
    e2.employee_name AS employee_2,
    e2.salary AS salary_2
FROM company_employee_salary e
LEFT JOIN company_employee_salary_2 e2
ON e.department = e2.department;


SELECT
    e.employee_id,
    e.employee_name,
    e.department,
    e.salary,
    e2.employee_name AS employee_2,
    e2.salary AS salary_2
FROM company_employee_salary e
RIGHT JOIN company_employee_salary_2 e2
ON e.department = e2.department;


CREATE TABLE employee_bonus (
    bonus_id INT PRIMARY KEY,
    employee_id INT,
    bonus_amount INT,
    bonus_year INT,

    FOREIGN KEY (employee_id)
    REFERENCES company_employee_salary(employee_id)
);

